const wallClock=value=>value?new Date(value).toLocaleTimeString('zh-CN',{hour12:false}):'—';
const stageNames={building:'搭建新场景',inference:'采集深度并运行 GraspNet',planning:'筛选可达抓取位姿',revalidating:'复核新鲜观测',zero:'零位观测',pregrasp:'预抓取运动',approach:'直线接近',close:'闭合夹爪',lift:'物理抬升',hold:'验证持物保持',place_lower:'回落到桌面',place_release:'松开夹爪',place_retreat:'退出物体',return_home:'返回零位',placed:'检查放置',exporting:'生成可视化与录像',done:'计算完成'};
async function fetchState(){const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error('本地仿真服务未连接');return r.json();}
function pollJob(){const timer=setTimeout(async()=>{try{const state=await fetchState(),job=state.job;if(!job||job.id!==jobId){busy=false;status('本次计算状态已变化，请刷新页面确认。','failed');controlsState();return;}
 if(job.status==='running'){status(`${stageNames[job.stage]||'正在计算'} · 开始 ${wallClock(job.started_at)} · 本阶段 ${wallClock(job.stage_started_at)}（${job.stage_elapsed_sec||0} 秒）· 总计 ${job.elapsed_sec||0} 秒。可自由旋转视角。`);pollJob();return;}
 busy=false;if(job.status==='done'){await loadExperiment(job.asset_base);status(`${job.message} · ${wallClock(job.started_at)} → ${wallClock(job.finished_at)}，总计 ${job.elapsed_sec||0} 秒`,job.success?'':'failed');if(metrics.selected)setPlaying(true);}else{loadTiming(`/runs/${job.id}/timeline.json`);resultBadge(job.status==='cancelled'?'计算已停止':'本次计算失败','failed');status(`${job.message} · ${wallClock(job.started_at)} → ${wallClock(job.finished_at)}，总计 ${job.elapsed_sec||0} 秒`,'failed');}controlsState();
 }catch(error){busy=false;status(`读取实验状态失败：${error.message}。刷新可恢复服务中的结果。`,'failed');controlsState();}},1000);return timer;}
$('#preview-multi').onclick=async()=>{if(busy||!backendReady)return;const p=readParameters();if(!p.multi_objects){status('先勾选桌面摆放多物体。','failed');return;}selectedPixel=null;$('#selected-pixel-marker').hidden=true;previewReady=false;status('正在从当前场景渲染 DC1 图像…');try{const r=await fetch('/api/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});const data=await r.json();if(!r.ok)throw Error(data.error||'预览失败');$('.camera-image img').src=data.image_url;previewObjects=data.objects||[];const selectionImage=new Image();selectionImage.src=data.selection_url;await selectionImage.decode();previewMaskCanvas=document.createElement('canvas');previewMaskCanvas.width=640;previewMaskCanvas.height=480;previewMaskCanvas.getContext('2d',{willReadFrequently:true}).drawImage(selectionImage,0,0);previewReady=true;setText('#target-selection-hint','请直接点击 DC1 图像中的五件物体之一；点中的物体就是本次抓取目标。');status('DC1 多物体预览已生成；请点选目标。');}catch(error){status(error.message,'failed');}};
$('.camera-image img').onclick=e=>{if(!loaded||busy||(dirty&&!previewReady)||(!previewReady&&metrics?.camera_source!=='dc1_rgbd')){status('请先运行当前场景，取得新的 DC1 图像后再点选目标。','failed');return;}const img=e.currentTarget,r=img.getBoundingClientRect(),scale=Math.min(r.width/img.naturalWidth,r.height/img.naturalHeight),left=(r.width-img.naturalWidth*scale)/2,top=(r.height-img.naturalHeight*scale)/2,u=Math.floor((e.clientX-r.left-left)/scale),v=Math.floor((e.clientY-r.top-top)/scale);if(u<0||u>=640||v<0||v>=480)return;if(readParameters().multi_objects){const objectId=previewMaskCanvas?.getContext('2d').getImageData(u,v,1,1).data[0]||0;const object=previewObjects.find(o=>o.id===objectId);if(!object){selectedPixel=null;$('#selected-pixel-marker').hidden=true;status('点击位置不属于可见的五个物体，请重新点选。','failed');return;}$('#target-kind').value=object.kind;status(`已选择${{bottle:'水瓶',apple:'苹果',small_carton:'小纸盒',can:'易拉罐',cup:'水杯'}[object.kind]}，运行后将只抓这个目标。`);}selectedPixel={u,v};const marker=$('#selected-pixel-marker'),container=$('.camera-image').getBoundingClientRect();marker.style.left=`${r.left-container.left+left+(u+.5)*scale}px`;marker.style.top=`${r.top-container.top+top+(v+.5)*scale}px`;marker.hidden=false;setText('#target-selection-hint',`已在 DC1 图像点选 ${$('#target-kind').selectedOptions[0].textContent}，像素 (${u}, ${v})。运行时只抓该目标。`);};
$('#run-experiment').onclick=async()=>{if(!backendReady||busy||!loaded)return;if(readParameters().multi_objects&&(!previewReady||!selectedPixel)){status('先生成多物体 DC1 预览并点选目标。','failed');return;}if(!readParameters().multi_objects)previewParameters();setPlaying(false);busy=true;resultBadge('真实仿真计算中','running');status('启动 MuJoCo，重新采集点云并规划…');controlsState();try{const r=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(readParameters())});const data=await r.json();if(!r.ok)throw Error(data.error||'启动失败');jobId=data.job.id;$('#run-log').href=data.job.log_url;$('#run-log').hidden=false;pollJob();}catch(error){busy=false;resultBadge('实验未启动','failed');status(error.message,'failed');controlsState();}};
